import random


class Snake:
    INITIAL_LENGTH = 1
    SCREEN_CENTER_FACTOR = 2
    POINTS_PER_FOOD = 100

    def __init__(self, SCREEN_WIDTH, SCREEN_HEIGHT, BLOCK_SIZE, food_position):
        self.length = self.INITIAL_LENGTH
        self.SCREEN_WIDTH = SCREEN_WIDTH
        self.SCREEN_HEIGHT = SCREEN_HEIGHT
        self.BLOCK_SIZE = BLOCK_SIZE
        self.positions = [(self.SCREEN_WIDTH / self.SCREEN_CENTER_FACTOR, self.SCREEN_HEIGHT / self.SCREEN_CENTER_FACTOR)]
        self.score = 0
        self.food_position = food_position

    def move(self, direction):
        cur = self.positions[0]
        x, y = direction

        new = self._calculate_new_position(cur, x, y)

        if new == self.food_position:
            self.eat_food()

        if self._has_collided(new):
            self.reset()
        else:
            self.positions.insert(0, new)
            if self._needs_to_shrink():
                self.positions.pop()

    def _calculate_new_position(self, current_position, x, y):
        return (
            (current_position[0] + (x * self.BLOCK_SIZE)) % self.SCREEN_WIDTH,
            (current_position[1] + (y * self.BLOCK_SIZE)) % self.SCREEN_HEIGHT,
        )

    def _has_collided(self, new_position):
        return len(self.positions) > 2 and new_position in self.positions[2:]

    def _needs_to_shrink(self):
        return len(self.positions) > self.length

    def random_food_position(self):
        while self.is_valid_food_position(self.food_position) is False:
            self.food_position = self._generate_random_food_position()

    def is_valid_food_position(self, position):
        return position not in self.positions

    def _generate_random_food_position(self):
        max_index_x = self.SCREEN_WIDTH // self.BLOCK_SIZE - 1
        max_index_y = self.SCREEN_HEIGHT // self.BLOCK_SIZE - 1
        return (
            random.randint(0, max_index_x) * self.BLOCK_SIZE,
            random.randint(0, max_index_y) * self.BLOCK_SIZE,
        )

    def reset(self):
        self.length = self.INITIAL_LENGTH
        self.positions = [(self.SCREEN_WIDTH / self.SCREEN_CENTER_FACTOR, self.SCREEN_HEIGHT / self.SCREEN_CENTER_FACTOR)]
        self.score = 0
        self.random_food_position()

    def eat_food(self):
        self.length += 1
        self.score += self.POINTS_PER_FOOD
        self.random_food_position()
